-- Laci schema for PostgreSQL. Generated by `pnpm --filter @lacijs/postgres schema`;
-- do not edit by hand. Equivalent to `PostgresStore#migrate()` with the default prefix.

CREATE TABLE IF NOT EXISTS laci_migrations (
  version     INT          PRIMARY KEY,
  name        VARCHAR(100) NOT NULL,
  applied_at  TIMESTAMPTZ  NOT NULL DEFAULT now()
);

-- 1: initial schema
CREATE TABLE laci_entries (
  id           UUID         PRIMARY KEY,
  key          VARCHAR(191) NOT NULL,
  kind         VARCHAR(20)  NOT NULL,
  environment  VARCHAR(50)  NOT NULL,
  locale       VARCHAR(35)  NOT NULL DEFAULT '',
  channel      VARCHAR(20)  NOT NULL DEFAULT '',
  description  TEXT,
  schema       JSON         NOT NULL,
  value        JSON         NOT NULL,
  status       VARCHAR(20)  NOT NULL,
  version      INT          NOT NULL,
  created_by   VARCHAR(255),
  updated_by   VARCHAR(255),
  created_at   TIMESTAMPTZ  NOT NULL DEFAULT now(),
  updated_at   TIMESTAMPTZ  NOT NULL DEFAULT now(),
  CONSTRAINT uq_laci_entries_address UNIQUE (key, environment, locale, channel),
  CONSTRAINT ck_laci_entries_kind CHECK (kind IN ('CONFIG', 'EMAIL_TEMPLATE', 'MESSAGE_TEMPLATE')),
  CONSTRAINT ck_laci_entries_status CHECK (status IN ('DRAFT', 'PUBLISHED', 'DISABLED')),
  CONSTRAINT ck_laci_entries_channel CHECK (channel IN ('', 'WHATSAPP', 'SMS', 'PUSH', 'IN_APP'))
);
CREATE INDEX idx_laci_entries_kind ON laci_entries (kind, environment);
CREATE TABLE laci_entry_histories (
  id          UUID        PRIMARY KEY,
  entry_id    UUID        NOT NULL REFERENCES laci_entries (id),
  version     INT         NOT NULL,
  value       JSON        NOT NULL,
  schema      JSON        NOT NULL,
  status      VARCHAR(20) NOT NULL,
  changed_by  VARCHAR(255),
  changed_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  note        TEXT,
  CONSTRAINT uq_laci_entry_histories_version UNIQUE (entry_id, version)
);
INSERT INTO laci_migrations (version, name) VALUES (1, 'initial schema');
